#include <array>
#include <cstddef>
#include <iostream>

using FilaOrigen = std::array<int, 3>;
using TablaOrigen = std::array<FilaOrigen, 2>;
using FilaDestino = std::array<int, 2>;
using TablaDestino = std::array<FilaDestino, 3>;

int main() {
    TablaOrigen original{};
    for (std::size_t fila = 0; fila < original.size(); ++fila) {
        for (std::size_t columna = 0; columna < original[fila].size(); ++columna) {
            if (!(std::cin >> original[fila][columna])) {
                std::cout << "Error de entrada\n";
                return 0;
            }
        }
    }
    TablaDestino transpuesta{FilaDestino{99, 99}, FilaDestino{99, 99},
                            FilaDestino{99, 99}};

    // Construye aqui los recorridos para transponer sin modificar original.
    // Cada valor debe quedar en la posicion que intercambia fila y columna.

    std::cout << "Original\n";
    for (std::size_t fila = 0; fila < original.size(); ++fila) {
        for (std::size_t columna = 0; columna < original[fila].size(); ++columna) {
            if (columna != 0) {
                std::cout << ' ';
            }
            std::cout << original[fila][columna];
        }
        std::cout << '\n';
    }
    std::cout << "Transpuesta\n";
    for (std::size_t fila = 0; fila < transpuesta.size(); ++fila) {
        for (std::size_t columna = 0; columna < transpuesta[fila].size(); ++columna) {
            if (columna != 0) {
                std::cout << ' ';
            }
            std::cout << transpuesta[fila][columna];
        }
        std::cout << '\n';
    }

    return 0;
}

